  function per(c) { var k = c && (c.persona || (HK.personaOf && HK.personaOf(c))) || 'gentle'; return PK.indexOf(k) >= 0 ? k : 'gentle'; }
  function isF(c) { return !!(HK.Pos && HK.Pos.isF && HK.Pos.isF(c)); }
