      if (t.night) k = t.outc === 'keep' ? 'keep' : t.outc === 'fwb' ? 'fwb' : t.outc === 'forget' ? 'forget' : (t.outc === 'lover' || pf.couple) ? 'lover' : 'unsure';
      else k = t.walk ? 'walkLove' : pf.couple ? 'couple' : 'walk';
