    var lk = loves ? 'love' : T.length ? 'pair' : 'none';
    ctx.say({ text: ctx.pick(GC_LAST[lk]).replace(/\{k\}/g, loves === 1 ? '一' : loves === 2 ? '二' : loves === 3 ? '三' : String(loves)), mag: 25, why: '結末：恋人になった組 ' + loves + '／一緒に帰った組 ' + T.length });
