      var sense = (nose(b) && nose(d) ? 18 : 6) + b.tr.a * 14 + b.tr.jealous * 14 + (BD.bonded(ctx, a, b) ? 12 : 0) + h.times * 6 - a.tr.a * 8 - a.tr.cp * 4 + ctx.rng() * 10;
