      var conf = a.tr.honesty * 0.8 + a.tr.np * 0.2 + a.tr.ac * 0.15 + a.stress / 400 + rab.trust / 400 - a.tr.cp * 0.4 - b.tr.jealous * 0.25 + (h.how === 'flaunt' || h.how === 'told' ? 0.2 : 0);
