    h.i = cast.si || 0; h.ng = ngOf(input.chars[h.i]); (function (c) { h.lock = c && c.loveLock !== '' && c.loveLock != null && !isNaN(+c.loveLock) ? +c.loveLock : null; if (HK.charFlags) HK.charFlags(c, h, 'hole'); })(input.chars[h.i]);
