      var p = HK.clamp(A.z / 100 * tm * (moved ? 1.3 : 0.75) * (1 - A.bar * 0.6) * (g.some(function (c) { return c.action.id === 'hunt'; }) ? 1.3 : 1) * 0.5, 0, 0.8);
      if (rng() > p) return;
