      out.text = ctx.pick(bait ? VIC.bait : VIC.shut).replace(/\{x\}/g, cold.name).replace(/\{v\}/g, v.name);
      out.why = cold.name + 'のドライさ（' + Math.round(cold.tr.cold * 100) + '）' + (bait ? 'と攻撃性。' + v.name + 'への緊張 ' + Math.round(ctx.R(cold, v).ten) : '');
      out.with = [cold];
