      var c = cs.sort(function (x, y) { return R(ctx, b, y).att + R(ctx, b, y).aff - R(ctx, b, x).att - R(ctx, b, x).aff; })[0];
      ctx.mod(a, b, { att: 5 }); ctx.mod(a, c, { ten: 10, aff: -4 });
