      if (sTop && HK.FM && HK.Pos.isF(p)) t = HK.FM.fixWith({ pick: function (a) { return pkF(S, a); } }, t, p, q.name);
      p.m.plea = 35; p.hs = 0; heatTr(p, 'melt');
