  var EPI_MOOD = { erased: 'forgot', body: 'forgot', neg: 'cold', report: 'cold', turn: 'cold', fail: 'cold', mid: 'wobble', warm: 'warm', couple: 'warm', peace: 'peace', fall: 'warm', depend: 'wobble' };
