  LK.GIMMICK.forEach(function (g) { G[g.id] = g; });
  if (G.cuff) {
    add(G.cuff.try, '{a}は手首をひねり、手錠の隙間から指を抜こうとした。|{a}は{b}の背中越しに、{b}の手錠の鍵穴を探った。二人の頬がぴったりとくっついた。|{a}は手錠の鎖をロッカーの角に何度も打ちつけた。|{a}は靴の中に隠していた細い針金を、つま先で器用に引っぱり出した。');
    add(G.cuff.ok, '手錠の片方がするりと抜けた。{a}は思わず声を上げそうになって、{b}に口を塞がれた。|カチャン、と金属音が響いた。ようやく、手首が軽くなった。|鍵穴の奥で、何かが噛み合う手応えがあった。手錠が、音もなく開いた。|手首に赤い痕を残して、手錠が外れた。{a}は痺れた指を、何度も握っては開いた。');
    add(G.cuff.ng, '指先が{b}の腰に触れてしまい、{a}は驚いて針金を取り落とした。|ガスのせいで指がうまく動かない。鍵穴が、何重にもぶれて見えた。|手錠が手首に食い込んだだけだった。{a}は小さく呻いた。|あと少しというところで、{b}が身じろぎした。その拍子に、針金がどこかへ消えた。');
  }
  if (G.code) {
    add(G.code.try, '{a}はダイヤルを回しながら、ぶつぶつと数字を唱えた。|{a}は貼り紙のヒントを、{b}の肩越しに何度も読み返した。「二人が初めて会った日……？」|{a}は思いつく限りの記念日を、片っ端からダイヤルに打ち込んだ。|{a}は目を閉じて、ダイヤルが噛み合う手応えを指先で探った。');
    add(G.code.ok, '最後の数字を合わせた瞬間、ロックが外れる重い音がした。|「……開いた」{a}は自分でも信じられないという顔をした。|四つの数字が揃い、ダイヤル錠がぱちんと弾けた。|ダイヤルを一つずらした途端、扉の内側で歯車が回り出した。');
    add(G.code.ng, '{a}は数字を一つ間違えた。ブザーが鳴り、ガスの噴き出す音が強くなった。|数字の6と9を見間違えた。ガスで、目の焦点が合わない。|{a}がダイヤルを回すたびに、肘が{b}の胸に当たった。三回目で、数字を忘れた。|「違う」「じゃあこれ」「それも違う」――二人の言い合いの間にも、ガスは濃くなっていった。');
  }
  if (G.puzzle) {
    add(G.puzzle.try, '{a}はからくり箱を胸の前で抱え、板を一枚ずつ指で押していった。|{a}は箱を{b}に持たせ、自分は後ろから手を回して板をずらした。|{a}はからくり箱を耳に当て、中で何かが転がる音を聞いた。|{a}は箱をひっくり返し、底の模様の向きを確かめた。');
    add(G.puzzle.ok, 'かちん、と軽い音がして、箱の引き出しがせり出した。中には、小さな銀色の鍵。|最後の板が滑った瞬間、箱が花のように開いた。|{a}は息を詰めて最後の板を押した。箱の中から、鍵が転がり落ちた。|「これだ」――箱の隠し引き出しから、鍵が顔をのぞかせた。');
    add(G.puzzle.ng, '板を押しすぎて、最初からやり直しになった。|箱が手から滑り、二人の太腿の間に挟まった。取ろうとすると、どうしても際どいところに手が入った。|からくり箱は、何度やっても同じところで止まった。|{a}は手順を思い出そうとしたが、{b}の吐息がうなじにかかって、頭が真っ白になった。');
  }
  if (G.vent) {
    add(G.vent.try, '{a}は爪先立ちになり、通気口のネジに指をかけた。体ごと{b}に預ける格好になった。|{a}は{b}の肩に足をかけ、通気口に手を伸ばした。|{a}はベルトのバックルをドライバー代わりにして、ネジを回し始めた。|{a}は通気口の格子に指を差し込み、力任せに引っぱった。');
    add(G.vent.ok, '最後のネジが、ころりと落ちた。カバーを外すと、奥にレバーが見えた。|格子が外れ、冷たい空気が一筋流れ込んだ。その奥に、開閉レバーがあった。|ネジが外れた瞬間、通気口の奥から非常灯の緑の光が漏れた。|{a}の指が、ついに通気口の奥のレバーに届いた。');
    add(G.vent.ng, 'バックルがネジ山から滑り、甲高い音が響いた。|背伸びした{a}の体が{b}の上でずり落ち、二人して変な声を出した。|通気口から、ガスが顔に直接吹きつけてきた。{a}は咳き込んで、手を離した。|ネジは一本だけ回った。残りの三本は、溶接されたように動かなかった。');
  }
  if (G.riddle) {
    add(G.riddle.try, 'スピーカーが問いかけた。「パンはパンでも、食べられないパンはなーんだ」|液晶に、三つの数字と一つの空欄が表示された。「\u2060空欄に入る数を答えよ」|スピーカーが、やけに色っぽい声でなぞなぞを読み上げた。|「二人の好きなものの頭文字をつなげよ」――液晶の文字が、ガスでにじんで見えた。');
    add(G.riddle.ok, '「……フライパン」{a}が答えると、ロッカーのどこかで錠が外れた。|スピーカーが拍手の効果音を流した。「お見事」|{a}の答えに、液晶が緑色に光った。|「正解です」――機械的な声が、なぜか少し悔しそうに聞こえた。');
    add(G.riddle.ng, '{a}が答える直前、{b}が太腿を擦り寄せてきた。答えは、甘い吐息になって消えた。|「不正解。ガス濃度を上げます」――スピーカーの声が、楽しそうだった。|{a}は答えを思いついたのに、口から出たのは{b}の名前だった。|二人で同時に別の答えを言ってしまい、どちらも無効になった。|{a}は答えを口にしかけて、{b}の吐息が首にかかった瞬間に言葉を失った。スピーカーが「時間切れ」と告げた。|{a}の声は甘い霧で掠れていて、機械には聞き取ってもらえなかった。|{a}は自信満々に答えたが、液晶は赤く光った。「……今の、絶対合ってたのに」');
  }
  if (G.kiss) {
    add(G.kiss.try, '扉のセンサーが点滅した。『キス、残り三十秒』|液晶にハートマークが表示された。『唇を重ねてください。照れは認識しません』|ロッカーの内側に、唇の形をしたセンサーが二つ並んでいた。|スピーカーが告げた。「キスで開きます。なお、ほっぺは不可」');
    add(G.kiss.ok, 'センサーのハートが満タンになり、扉のロックが外れた。二人の唇は、それでもまだ離れなかった。|三十秒のカウントが終わっても、二人は唇を重ねたままだった。扉は、とっくに開いていた。|「認証完了」の声が、ずいぶん遠くに聞こえた。|ピッ、と軽い音がした。扉が開いたことに、二人が気づいたのは少し後だった。');
    add(G.kiss.ng, '二人は唇を寄せては離れ、を三回繰り返した。センサーは一度も反応しなかった。|キスの途中で{b}が笑ってしまい、カウントがリセットされた。|「……やっぱり無理」――{a}は真っ赤な顔で、顔をそむけた。|二十九秒目で、{a}の息が続かなくなった。');
  }
  if (LK.PLOT && LK.PLOT.hide) {
    add(LK.PLOT.hide.cuff, '{a}は自分の手錠の鍵を、そっと口の中に隠した。|{a}は拾った針金を、わざと通気口の隙間に落とした。');
    add(LK.PLOT.hide.code, '{a}はヒントの紙を、こっそり裏返した。|{a}は正しい数字が分かっていたのに、一つだけずらしておいた。');
    add(LK.PLOT.hide.puzzle, '{a}は箱の最後の板を、知らないふりで押さえつけていた。|{a}はからくり箱を、わざと足元の奥に蹴りやった。');
    add(LK.PLOT.hide.vent, '{a}は「届かない」と言いながら、わざと背伸びしなかった。|{a}は外したネジを、もう一度こっそり締め直した。');
    add(LK.PLOT.hide.riddle, '{a}は答えを言いかけた{b}の口を、自分の唇で塞いだ。|{a}は「たぶん違う」と言って、{b}の正しい答えを止めた。');
    add(LK.PLOT.hide.kiss, '{a}はキスの途中で、わざと少しだけ唇をずらした。|{a}は「もう一回」と言って、カウントが終わる直前に離れた。');
  }
  add(LK.QUIET, 'どちらかの喉が、ごくりと鳴った。二人とも、それが自分ではないふりをした。|{a}は目をつぶった。見なければ平気だと思った。かえって、{b}の匂いと体温だけがはっきりした。|ロッカーの外で、時計の秒針がやけに大きく聞こえた。|{b}の髪が、{a}の頬をくすぐった。払いのける手すら、自由にならなかった。|二人は互いの肩に額をのせたまま、じっと嵐が過ぎるのを待った。過ぎる気配はなかった。|{a}は話題を探して、「……今日、何食べた？」と訊いた。{b}は答えられなかった。|汗が一筋、{a}のこめかみから首へ伝った。{b}の視線が、それを追いかけた。|狭い箱の中で、二人の膝がぶつかった。どちらも、膝を引かなかった。|{a}はわざと難しいことを考えようとした。九九の七の段で、三回間違えた。|{b}が小さく咳払いをした。その振動が、密着した胸を通して{a}に伝わった。');
  add(LK.KISS_OK, '「早く終わらせよう」と言ったのは{a}だった。唇が触れた瞬間、二人ともその言葉を忘れた。|{b}は目を閉じて、少しだけ顎を上げた。{a}は、ゆっくりと唇を重ねた。|二人の唇が触れた。三十秒は、思っていたよりずっと長くて、思っていたよりずっと短かった。|「数えてて」と{a}が言った。{b}は数えるのを、十二で忘れた。');
  add(LK.OUTSIDE, 'ロッカーの外で、何かが倒れる音がした。その衝撃で、扉のロックが外れた。|「点検でーす」――作業着の男が、何も知らずに扉を開けた。そして、すぐに閉めた。|ガスの噴き出す音が、ぷすん、と止まった。続いて、扉のロックが外れる音がした。|停電だった。電子錠が、非常モードで一斉に解除された。');
  add(LK.GAS[0], '{a}は、喉の奥に甘い味が残っているのに気づいた。舐めた唇まで、甘かった。|{a}の耳たぶが、じんじんと熱を持ち始めた。|{a}はなんとなく、{b}の首筋から目が離せなくなった。理由は、自分でも分からなかった。|甘い霧が、{a}の睫毛にまとわりついた。まばたきするたび、世界が少しずつ柔らかくなっていく。');
  add(LK.GAS[1], '{a}の指先が、勝手に{b}の服の裾をつまんでいた。|{a}は自分の鼓動が、{b}に聞こえているのではないかと気が気でなかった。|{b}が身じろぎするたび、触れたところから甘い痺れが走った。{a}は小さく息を呑んだ。|{a}は、{b}の吐息がかかった首筋を、無意識に{b}の方へ傾けていた。');
  add(LK.GAS[2], '{a}の膝から力が抜けた。{b}にもたれかかっていないと、立っていられなかった。|{a}は自分の唇を何度も舐めた。乾いているわけでもないのに。|{a}の腰が、ほんの少しだけ前に出た。気づいて引こうとして、引けなかった。|{a}の視界の端が、桃色にぼやけていた。{b}の輪郭だけが、やけにくっきりしていた。');
  add(LK.GAS[3], '{a}の吐息は、もう声に近かった。言葉にしようとすると、全部甘い音になった。|{a}は{b}の胸に顔を押しつけて、震えを止めようとした。止まらなかった。|{a}の体は、{b}がほんの少し触れるだけで跳ねるようになっていた。|{a}の目尻から、熱で潤んだ涙がこぼれた。悲しくもないのに。');
  add(LK.SURGE, 'ガスの噴き出し口が、一斉に開いた。視界が一瞬で桃色に染まった。|スピーカーが「ボーナスタイム！」と叫び、ガスの勢いが倍になった。|ロッカーごと誰かに運ばれているらしい。揺れるたびに、二人の体が擦れ合った。|天井から、ぽたり、と甘い雫が落ちてきた。それが{a}の首筋を伝うと、{a}は思わず声を漏らした。|ロッカーの中の温度が急に上がった。汗で、服が肌に張りついた。|足元の床が振動し始めた。止まる気配はなかった。|照明が赤く点滅した。警告音が、なぜか鼓動と同じリズムだった。|扉の隙間がわずかに狭まり、二人はさらに押しつけられた。');
  add(LK.CALM, 'ガスの噴き出しが、一瞬だけ止まった。二人は大きく息を吐き、顔を見合わせた。|{a}は{b}の肩に額を押しつけて、ゆっくり十数えた。少しだけ、頭がはっきりした。|{b}が「大丈夫、大丈夫」と小さく繰り返した。その声で、{a}は少し落ち着いた。|扉の隙間から、外の冷たい空気がすっと入ってきた。|{a}は自分の太腿をつねった。痛みで、ほんの少しだけ正気が戻った。|二人は示し合わせたように、同時に深呼吸した。三回目で、同時に笑ってしまった。');

  /* ---------- 手を出す（{a}が仕掛ける側） ---------- */
  var A = LK.ACT;
  add(A.touch.t, '{a}の指が、{b}の脇腹をなぞった。止めようとしたのに、止まらなかった。|{a}は{b}の背中に回した手で、背骨を一つずつ確かめるように撫で下ろした。|{a}の手のひらが、{b}の腰骨の上で止まった。そのまま、離れなかった。|{a}は{b}の首筋に鼻先を寄せ、匂いを吸い込んだ。|{a}の膝が、{b}の膝の間にそっと割り込んだ。|{a}は{b}の指に、自分の指を絡めた。それだけで、二人とも息が上がった。');
  add(A.touch.bound, '{a}は後ろ手のまま、{b}の首筋に額をすりつけた。|{a}は手が使えない代わりに、太腿で{b}の太腿を挟んだ。|{a}は手の使えない体を、ゆっくりと{b}に擦りつけた。');
  add(A.kiss.t, '{a}は{b}の下唇を、軽く噛んだ。|{a}は{b}の頬に、こめかみに、まぶたに、次々と唇を落とした。|{a}は{b}の顎を指で持ち上げ、逃げられないようにしてから口づけた。|{a}は{b}の耳の後ろに唇を押しあて、そこで小さく名前を呼んだ。|{a}の唇が、{b}の鎖骨の上をゆっくりと這った。|{a}は{b}の唇を舌でなぞった。{b}の口が、勝手に開いた。');
  add(A.kiss.bound, '{a}は後ろ手のまま首を伸ばし、{b}の顎の先に口づけた。|{a}は手の使えない体で{b}にもたれかかり、首筋に吸いついた。|{a}は手を使えないぶん、何度も何度も{b}の唇を求めた。');
  add(A.grope.t, '{a}の手が、{b}のシャツの裾から滑り込み、素肌の腹を撫で上げた。|{a}は{b}の太腿の内側を、膝から付け根まで、ゆっくりとなぞり上げた。|{a}は{b}の背中に手を回し、服の上から胸の先を探り当てた。|{a}の指が、{b}のベルトのバックルにかかった。|{a}は{b}の耳を甘噛みしながら、服の上から一番熱いところを手のひらで包んだ。|{a}は{b}の腰を引き寄せ、自分の熱を押しつけた。');
  add(A.grope.bound, '{a}は後ろ手のまま、膝で{b}の脚の間をゆっくりと押し上げた。|{a}は動かせる腰だけで、{b}に何度も熱を押しつけた。');
  add(A.oral.t, '{a}は狭い隙間で体を折り、{b}の服をずらして、そこに唇を寄せた。|{a}はロッカーの壁に背中を擦りながらしゃがみ込み、{b}の脚の間に顔を埋めた。|{a}は{b}を見上げたまま、ゆっくりと舌を這わせた。|{a}は{b}の太腿にしがみつくようにして、熱を帯びたところを口に含んだ。');
  add(A.oral.bound, '{a}は後ろ手のまま膝をつき、顔だけで{b}の服をかき分けた。|{a}は手の使えない体を折り曲げ、唇だけで{b}を探り当てた。');
  add(A.sex.t, '{a}は{b}の腰を抱え上げ、ロッカーの壁に押しつけたまま、ゆっくりと奥まで沈めた。|{a}は{b}の片膝を自分の腰に引っかけさせ、下から突き上げるようにして繋がった。|{a}は{b}を後ろ向きにさせ、ロッカーの扉に手をつかせてから、腰を引き寄せた。|{a}は{b}の唇を塞いだまま、狭い箱の中で、深く{b}の中に入っていった。|{a}は{b}の腰を両手で固定し、ほとんど動けない隙間で、小刻みに奥を突いた。|{a}は{b}の耳元で「力抜いて」と囁いてから、ゆっくりと繋がった。');
  add(A.sex.bound, '後ろ手のままの{a}は{b}の腰に脚を絡め、自分から{b}を迎え入れた。|{a}は後ろ手のまま、{b}に背中を預け、腰を押しつけて{b}を自分の中に導いた。');
  add(A.sex.ride, '{a}は{b}の肩につかまって伸び上がり、そのまま{b}の上にゆっくりと腰を落とした。|{a}は{b}の腰に脚を巻きつけ、狭いロッカーの中で、自分から{b}を奥まで受け入れた。|{a}は{b}の首に腕を回し、耳元で「動かないで」と言ってから、自分のペースで{b}を迎え入れた。|{a}はロッカーの壁に背中を預け、{b}の腰を引き寄せて、自分の中へ導いた。|{a}は{b}に背を向け、扉に額を押しつけたまま、腰を沈めて{b}を受け入れた。|{a}は{b}の手を自分の腰に添えさせ、その手に導かれるようにして{b}の上に沈んだ。');
  add(A.sex.boundTop, '後ろ手のままの{a}は、{b}の脚の間に腰を割り込ませ、そのまま奥まで押し入った。|{a}は手を使えないまま、{b}の体を壁と自分の間に挟み込み、腰だけで{b}を貫いた。');

  add(LK.ACCEPT, '{b}は{a}の手を、振りほどくどころか、もっと強く自分に押しあてた。|{b}は小さく息を吐いて、{a}の肩に頬を預けた。それが答えだった。|{b}は黙って目を閉じた。睫毛が、小刻みに震えていた。|{b}の手が、{a}の背中にそっと回された。|{b}は「……ずるい」と呟いて、自分から{a}に唇を寄せた。|{b}の体から、ふっと力が抜けた。');
  add(LK.REFUSE, '{b}は首を振った。「だめ。今は、だめ」|{b}は{a}の胸に手をついて、わずかに距離を取った。「……ガスのせいだよ」|{b}は{a}の手首を、自分の腰からそっと外した。「出てから。ね」|{b}は唇を引き結び、{a}から顔をそむけた。耳まで真っ赤だった。|{b}は「こら」と小さく叱って、{a}の額を指で弾いた。|{b}は深く息を吸って、「先に、仕掛け」とだけ言った。');
  add(LK.PASSIVE, '{b}は止めようと口を開いたが、出てきたのは甘い吐息だけだった。|{b}は{a}の服を掴んで押し返そうとして、逆に引き寄せてしまった。|{b}の「やめて」は、どんどん小さくなっていった。|{b}は目を閉じた。拒む理由を探しているうちに、拒むのを忘れた。');
  var AS = LK.ACCEPT_SAY;
  add(AS.proud, '「……文句は、出てから聞く」|「……好きにしろ。どうせ、こっちも同じだ」|「止まれないなら、止まらなくていい」|「……後で後悔しても知らねえぞ」');
  add(AS.stern, '「……わかった。もう、拒まない」|「……こうなった以上、半端にはしない」|「……誰にも言うな。それだけだ」|「……正直に言う。私も、限界だった」');
  add(AS.tsun, '「し、仕方ないから！　今だけだから！」|「……ばか。もっと早く言いなさいよ」|「ちょ、ちょっとだけなら……いいけど……」|「べ、別にあんたのためじゃないし……ガスのせいだし……」');
  add(AS.gentle, '「大丈夫。わたしも、同じ気持ちだから」|「無理しないで。……ほら、こっち」|「ゆっくりね。ゆっくり」|「いいよ。……全部、受け止めてあげる」');
  add(AS.devoted, '「ずっと、こうしてほしかったんです……」|「あなたが望むなら、何でも」|「離さないで、ください……」|「わ、私で……いいんですか……？」');
  add(AS.cool, '「……もう、取り繕うのはやめる」|「……隠しても無駄だな。お互いに」|「……来いよ。こっちも、余裕がない」|「……今だけは、何も考えないことにする」');
  add(AS.free, '「やったー！　ちょうど同じこと考えてた！」|「ねえ、もっとくっつこ？」|「どうせなら楽しもうよ、ね？」|「いいよいいよ、全部ガスのせいにしちゃお！」');
  add(AS.shy, '「は、恥ずかしい、けど……いや、じゃない、です……」|「……う、うん……」|「め、目、つぶってて、ください……」|「や、やさしく、なら……」');
  add(AS.polite, '「……では、失礼して」|「わたくしでよろしければ……」|「……お気持ち、確かに受け取りました」|「どうか、お手柔らかに……」');
  var RS = LK.REFUSE_SAY;
  add(RS.proud, '「離れろ。……今は、それが一番マシだ」|「勘違いするな。お前が嫌なわけじゃない」|「手を出したら、出た後でぶん殴る」|「……集中しろ。出口が先だ」');
  add(RS.stern, '「待て。……ここで流されたら、二人とも後悔する」|「手を引け。今のお前は、お前じゃない」|「……気持ちは分かる。だが、今じゃない」|「深呼吸しろ。私も、そうする」');
  add(RS.tsun, '「な、何考えてんのよ！　出てからにしなさいよ！」|「ば、ばかばか！　今そういう空気じゃないでしょ！」|「……あとで、ちゃんと言ってくれたら、考える……」|「触らないで！　……い、嫌なわけじゃ、ないけど……」');
  add(RS.gentle, '「ね、ちょっとだけ我慢しよう。一緒に」|「つらいね。でも、出てからにしよ？」|「大丈夫、すぐ出られるから。ね」|「手、繋ごうか。それだけにしよう」');
  add(RS.devoted, '「あ、あなたのためにも……今は、だめです……」|「わ、私、耐えますから……一緒に……」|「ほ、本当は……でも、だめです……っ」|「出たら……その時は、ちゃんと……」');
  add(RS.cool, '「落ち着け。今動いても、何もいいことはない」|「……ガスが言わせてるだけだ。分かってるだろ」|「手を止めろ。……先に出口だ」|「それは、ここを出てから考えよう」');
  add(RS.free, '「だーめ！　出るまでおあずけ！」|「ちょ、くすぐったいって！　今は脱出優先！」|「あとで！　あとでね！」|「もー、ガスに負けすぎ！」');
  add(RS.shy, '「ま、まって、まってください……っ」|「い、今は……こわい、です……」|「そ、そういうのは……出て、から……」|「……っ、だ、だめ……」');
  add(RS.polite, '「恐れ入りますが、今はご辛抱ください」|「お気持ちは嬉しいのですが……ここでは」|「申し訳ありません。今は、仕掛けを優先させてください」|「……後ほど、改めて」');
  add(LK.NAMA, '{a}と{b}は、手錠のまま額と額を押しつけ合っていた。触れたい場所に、どちらの手も届かない。|服越しに擦れ合うだけの熱が、かえって体の奥を焦がしていった。{a}は唇を噛んで呻いた。|{b}の吐息が首筋にかかるたび、{a}の体が跳ねた。それ以上は、何もできなかった。|二人は互いの肩に顔を埋めて、腰だけを小さく揺らしていた。届かない。どうしても、届かない。|{a}は拘束具を引きちぎろうともがいた。もがくたびに体が{b}に擦れて、また力が抜けた。|触れられないまま、{a}は小さく達しかけて、寸前で引き戻された。泣きそうな声が漏れた。|{a}の「お願い」は、{b}に向けたものだったのか、手錠に向けたものだったのか、本人にも分からなかった。|二人は吐息だけで互いを求め合っていた。ロッカーの中が、二人分の熱で白く曇った。');
  add(LK.TEASE, '繋がったまま身動きが取れず、{a}は{b}の肩に歯を立てて、焦れったさに耐えた。|ロッカーが軋むたび、ほんのわずかに奥が擦れる。そのわずかさが、二人を狂わせた。|「動きたい」と{b}が泣きそうな声で言った。「……動けない」と{a}が答えた。|奥まで届いているのに、そこから先に進めない。{a}と{b}は、ただ互いを強く抱きしめ合った。|{b}の中がきゅっと締まるたび、{a}の喉から呻きが漏れた。動けない分、全部がそこに集まっていた。|二人は、ほんの数ミリの揺れだけで、何度も達しかけた。');
  add(LK.ONE.help, '{b}は発情した{a}の髪を撫でて、「もう少し、もう少し」と言い聞かせた。|{b}は{a}の手を握って、自分の胸に当てさせた。「ほら、深呼吸。一緒に」|{b}は{a}の熱い額に自分の額を合わせて、冷ますようにじっとしていた。|{b}は{a}の耳元で、落ち着いた声で数を数え続けた。');
  add(LK.ONE.give, '{b}は「見ないでいてあげるから」と言って、{a}の熱をそっと手のひらで包んだ。|{b}は{a}の震える背中を抱き寄せ、空いた手で{a}を楽にしてやった。|{b}は少し迷ってから、{a}の服の中に手を入れた。「……こうすれば、少しは楽？」|{b}は「声、我慢しなくていいよ」と囁き、{a}が果てるまで手を止めなかった。');
  add(LK.ONE.tempted, '{b}は首を振って正気を保とうとした。けれど、{a}の潤んだ目を見たら、首を振るのをやめてしまった。|{a}の甘い声を聞いているうちに、{b}の呼吸も浅くなっていった。|{b}は「だめ、だめ」と言いながら、{a}の頬に触れた手を離せなかった。|{a}の熱が、密着した体越しに{b}にもうつっていった。');
  add(LK.SERVANT.hold, '{a}は主の肩越しに壁を睨みつけ、ひたすら呼吸を数えていた。|{a}は自分の腕に爪を立て、主から意識を逸らそうとした。「……失礼を、いたしません」|{a}は額に脂汗を浮かべながら、主の体に触れないよう、ぎりぎりのところで腰を引き続けた。|{a}「どうか、私を見ないでください。……目が合えば、耐えられません」');
  add(LK.SERVANT.break, '{a}は低く呻いて、主の首筋に顔を埋めた。「申し訳、ありません……もう……」|{a}の手が、震えながら主の腰を引き寄せた。「お叱りは、後でいくらでも」|「……もう、無理です」――{a}は主の唇を、許しも得ずに奪った。|{a}は主の名前を、初めて敬称をつけずに呼んだ。');
  add(LK.SERVANT.order, '{b}は{a}の耳元で囁いた。「よく耐えた。……褒美だ」|{b}は{a}の頬に手を添え、「顔を上げろ。私を見ろ」と言った。{a}の目から、最後の理性が消えた。|{b}は「許す」とだけ言った。それで十分だった。|{b}は{a}の手を取り、自分の腰に導いた。「命令だ。触れろ」');
  add(LK.PLOT.reveal, '{a}は{b}の耳元で囁いた。「ガス、止める方法も知ってるよ。……止めないけど」|{a}は悪びれもせずに言った。「鍵、最初から持ってたんだ」|{a}は甘い霧の中で、{b}の手を握った。「ずっと、二人きりになりたかった」|{a}は悪びれもせずに、この部屋を借りたのは自分だと白状した。|{a}は{b}の唇に指を当てた。「大声出さないで。……誰も来ないから」|{a}は「怒った？」と小首をかしげた。その目は、少しも反省していなかった。');
  add(LK.PLOT.push, '{a}は{b}が目を覚ます前から、{b}の胸に頬を寄せていた。|{a}は「怖い」と言って{b}にしがみついた。その声は、少しも怖がっていなかった。|{a}は自分からガスの噴き出し口に顔を向け、深く息を吸った。|{a}は{b}の手を取って、そっと自分の腰に回させた。');

  /* ---------- ベッド（{a}が攻め） ---------- */
  var B = LK.BED;
  add(B.timeout, 'ブザーとともに扉が開いた。外の部屋の真ん中には、清潔なシーツの大きなベッドが一つ。二人は顔を見合わせることもなく、そちらへ歩いた。|時間切れのアナウンスが流れ、ロックが外れた。けれど二人の足は、出口とは逆の方へ向かった。|扉が勝手に開いた。外の空気は冷たかった。二人の体は、少しも冷めなかった。|制限時間が過ぎ、ロッカーの扉がゆっくりと開いた。二人はもつれ合ったまま、外の床に崩れ落ちた。');
  add(B.start, '扉が開くと同時に、二人は互いの手を掴んだ。どちらから、というのは分からなかった。|外に出た二人の目に入ったのは、出口の扉ではなく、部屋の隅の大きなベッドだった。|外に出られた安堵は、一秒ももたなかった。二人はロッカーの扉が閉まるのも待たずに、唇を重ねた。|二人はよろめきながらロッカーを出た。外の部屋は静かで、ベッドが一つだけ置かれていた。|扉が開いた。二人は顔を見合わせ、それから同時に、出口ではない方へ一歩踏み出した。|ロッカーから出た瞬間、{a}は{b}の腕を掴んで引き寄せた。もう、狭い箱の言い訳は要らなかった。');
  add(B.strip, '{a}は{b}のシャツを頭から脱がせ、床に放り投げた。|{b}は{a}のベルトを外しながら、指が震えて三回失敗した。|二人は相手の服を脱がせることに夢中で、自分の服を脱ぐのを忘れていた。|{a}は{b}の服の留め具を一つずつ外していった。外すたびに、露わになった肌に口づけた。|{b}は自分で服を脱ぎ捨て、{a}の前に立った。耳まで赤かった。|服は、ベッドに辿り着くまでの間に全部床に落ちていた。');
  add(B.fore, '{a}は{b}の指を一本ずつ口に含んだ。ロッカーの中で触れられなかった分を、取り返すように。|{a}は{b}の背中に唇を這わせ、腰のくぼみで止まった。{b}の体がびくりと跳ねた。|{a}は{b}の胸に顔を埋め、舌と指で、{b}が一番反応する場所を探し当てた。|{a}は{b}の両手をシーツに縫いとめ、首筋から下腹まで、ゆっくりと口づけを落としていった。|{a}は{b}の膝の裏に口づけた。そんな場所で感じると、{b}は知らなかった。|{a}は{b}の内腿に歯を立て、そこからゆっくりと上へ舌を這わせた。');
  add(B.insert, '{a}は{b}の脚を自分の肩に担ぎ上げ、深く、一息に繋がった。{b}の背中が弓なりに反った。|{a}は{b}を横向きに寝かせ、後ろから抱きしめる形で、ゆっくりと{b}の中に入っていった。|{a}は{b}の腰の下に枕を差し込み、角度を確かめてから、奥まで沈めた。|{a}は{b}を膝の上に抱き上げ、向かい合ったまま、下から{b}を貫いた。|{a}は{b}の両手首を片手でまとめ、もう片方の手で{b}の腰を引き寄せて繋がった。|{a}は{b}の額に口づけてから、焦らすようにゆっくりと、一番奥まで入っていった。');
  add(B.pos, '{a}は体位を変えるたびに、{b}の一番弱いところを新しく見つけていった。|{b}が「もう無理」と言うたびに、{a}は「あと一回」と囁いた。|ベッドの軋む音と、二人の声と、シーツの擦れる音だけが、部屋に満ちていた。|二人は何度も体勢を変えてシーツの上を転がりながら、それでも繋がりだけは解かなかった。|{a}は{b}をうつ伏せにさせ、背中に覆いかぶさった。{b}の指が、シーツを握りしめた。|ガスの名残が、二人の感覚をどこまでも鋭くしていた。触れるところ全部が、熱かった。');
  add(B.climax, '{a}は{b}の名前を呼びながら、{b}の一番奥で果てた。{b}も、それに引きずられるように震えた。|{b}が三度目に達したとき、{a}もようやく限界を迎えた。二人はしばらく、繋がったまま動かなかった。|最後は、二人とも声にならない声を上げた。気づけば、互いの指が痛いほど絡み合っていた。|{a}が果てた瞬間、{b}は{a}の背中に爪を立てた。赤い痕が、くっきりと残った。|二人はほとんど同時に果て、そのまま重なり合うように倒れ込んだ。|{a}は{b}の中で何度目かの熱を吐き出した。ガスの熱は、ようやく引き始めていた。');
  add(B.rough, '{a}は{b}の髪を掴んで顔を上げさせ、「さっきの続きだ」と囁いてから、深く突いた。|「誰のせいでこうなったと思ってる」――{a}は{b}の腰を掴み、容赦なく奥を抉った。|二人は互いの名前を罵るように呼び合いながら、何度も何度も求め合った。|{b}は{a}の肩に噛みつき、{a}は{b}の首筋に痕を残した。どちらも、手加減を忘れていた。');
  add(B.sweet, '{a}は動きを止めて、{b}の顔をじっと見つめた。「……きれい」|二人はキスをやめないまま、ゆっくりと揺れ続けた。急ぐ理由は、もうなかった。|{b}が「好き」と言うと、{a}は「知ってた」と笑って、もっと深く抱きしめた。|{a}は{b}の涙に気づいて、動きを止めた。「痛い？」「……うれしいだけ」');

  /* ---------- 脱出のあと ---------- */
  var F = LK.AFTER;
  add(F.clean, '外の空気を吸った瞬間、二人は膝から崩れ落ちた。そして、なぜか大笑いした。|二人は出口の前で一度だけ振り返った。ロッカーは、何事もなかったように静かだった。|「お疲れ」「……お疲れ」――二人はそれだけ言って、別々の方向に歩き出した。少しだけ、名残惜しそうに。|扉を出た瞬間、{a}は{b}の背中をばしんと叩いた。「よく耐えた！」「そっちこそ」');
  add(F.near, '二人は無言で出口に向かった。並んで歩く手が、一度だけ触れて、すぐに離れた。|{b}は「……あの時、止めてくれてありがとう」と小さく言った。{a}は聞こえないふりをした。|外に出た{a}は、自分の手のひらをじっと見つめた。さっき{b}に触れかけた手だった。|「さっきのは、なかったことに」「……うん」――二人とも、なかったことにはできそうになかった。');
  add(F.awkward, '帰り道、二人は三歩ずつ距離を空けて歩いた。でも、同じ駅で降りた。|{b}は乱れた襟元を直しながら、{a}と目を合わせないまま「……ガスって怖いね」と言った。|外に出た二人は、同時に「さっきのは」と言いかけて、同時に黙った。|翌日、二人はいつも通りに挨拶をした。ただ、少しだけ声が上ずっていた。');
  add(F.angry, '{b}は振り返りもせずに出口へ向かった。「……二度と顔を見せないで」|{b}は乱れた服を整え、{a}を睨みつけた。「ガスのせいにしたら、許さないから」|外に出るなり、{b}は{a}のすねを思い切り蹴った。「これで勘弁してあげる」|{b}は一言も口をきかなかった。ただ、別れ際に{a}の頬を軽く叩いていった。');
  add(F.plotwin, '{a}は眠る{b}の寝顔を見ながら、次はどの部屋を借りようか考えていた。|{a}は{b}の髪に口づけて、小さく「計画通り」と呟いた。|{a}は{b}が眠ったのを確かめてから、ロッカーの中に隠していた鍵を、そっとゴミ箱に捨てた。|{a}は満ち足りた顔で天井を見上げた。{b}がいつ真相に気づくかは、また別の話だ。');
  add(F.plotfail, '{a}は扉が開いた瞬間、心の中で舌打ちした。こんなに早く開くはずじゃなかった。|{b}は{a}の手から鍵を取り上げた。「……最初から持ってたよね、これ」|{a}の計画は、{b}の理性の前にあっさり崩れた。{a}は帰り道、ずっと黙っていた。|{b}は{a}をじっと見た。「……次は、普通に誘って」');
  add(F.rescue, 'ロックが外れたのは、時間切れぎりぎりだった。二人とも、ほとんど意識が朦朧としていた。|扉が開いても、二人はしばらく動けなかった。ガスの名残が、まだ体の芯に燻っていた。|二人は這うようにしてロッカーから出た。床の冷たさが、ありがたかった。|時間切れのブザーが鳴り響いた。扉の向こうでは、救急セットを抱えたスタッフが待っていた。');
  function L(s) { return s.split('|'); }
  /* ---------- ノリノリの受け：自分から跨る・誘う（{a}=誘う／跨る側＝受け、{b}=攻め） ---------- */
  if (LK && LK.ACT && LK.ACT.sex) {
    LK.ACT.sex.nori = L('{a}は{b}の首に腕を回し、「もう我慢しなくていいよね？」と笑って、自分から{b}の上に腰を落とした。|{a}は{b}の手を掴んで自分の腰に導き、耳元で「……挿れて。今すぐ」と囁いた。{b}が応えるより先に、{a}の方から{b}を迎え入れていた。|{a}は狭いロッカーの中で器用に体をひねり、{b}に背中を押しつけた。「ほら、こっち」――{a}は自分から{b}を奥まで飲み込んだ。|{a}は{b}の膝に片脚をかけ、「動かなくていいから」と言って、自分のペースで{b}を受け入れた。|{a}は「こういうの、嫌いじゃないでしょ？」と{b}の唇を舐め、そのまま自分から腰を沈めた。');
    LK.ACT.sex.noriBound = L('後ろ手のままの{a}は、{b}の腰に脚を絡めて引き寄せた。「手がなくても、できるよ？」――{a}は自分から{b}を迎え入れた。|{a}は後ろ手のまま{b}に背中を預け、腰を揺らして誘った。「……ねえ、挿れて」');
  }
  if (LK && LK.BED) {
    LK.BED.noriInvite = L('ロッカーの扉が開くなり、{q}は{o}の手を引いてベッドに飛び込んだ。「続き、しよ！」|{q}はベッドの真ん中に寝転がり、両腕を広げた。「ほら、来て」|{q}は{o}をベッドに押し倒し、上から顔をのぞきこんで笑った。「今度は逃げられないよ？」');
  }
