    A.notes.push('耐えた ' + A.cnt.hold + '回' + (A.cnt.self ? '・一人で ' + A.cnt.self + '回' : '') + (A.cnt.solve ? '・仕掛けを解いた ' + A.cnt.solve + '回' : ''));
