      tsun: [L('ちょ、っと……そこ、ばっかり……|ん、ぁ……っ、べつに、平気なんだから……|や、ぁ……っ、聞こえちゃう、ってば……'), L('や、ぁあっ……だめ、イっちゃう……っ|ん、ぅうっ……ばか、ばか……っ！|ひ、ぁっ……もう、知らない……っ')],
