          say({ actors: [p.i, ex2.i], tag: '裏切り', text: F(pk(J.betray), { a: p.name, x: ex2.name }) + F(pk(J.betrayed), { a: p.name, x: ex2.name }), why: p.name + 'は' + ex2.name + 'と組んでいたが、疑いが上回った（' + Math.round(p.sus[ex2.i]) + '）' });
