    if (!txt) return null;
    var dB = stg >= 2 ? { ten: 8, aff: -2 } : { att: 2, ten: 3 };
    ctx.mod(a, b, { att: 3 });
    ctx.mod(b, a, dB);
    if (key === 'purge2' && c) { ctx.mod(c, a, { ten: 14, aff: -10 }); ctx.mod(a, c, { ten: 10 }); ctx.stress(c, 8); }
    if (ty === 'depend' && stg >= 2) { ctx.stress(a, 10); ctx.stress(b, 8); }
